"""Original footer function/CSS with example branch states; viewport media queries remain real."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download'
source=(r/'docs/replica/source/original.js').read_text().splitlines()
defs='\n'.join(x for x in source if x.startswith(('const icons=','const icon=','const t=','const btn=','function footer()','function press(')))
variants=[('home',{}),('connect',{}),('connect-busy',{'screen':'connect','busy':True}),('connected',{'screen':'connect','connected':True}),('connected-busy',{'screen':'connect','connected':True,'busy':True}),('capabilities',{}),('select-none',{'screen':'select','selected':[]}),('select-no-table',{'screen':'select','tables':[]}),('select-trial-unready',{'screen':'select','selected':['data','trial']}),('select-trial-ready',{'screen':'select','selected':['data','trial'],'trial':{'ready':True}}),('select',{}),('trial',{}),('trial-consented',{'screen':'trial','trial':{'consent':True}}),('trial-ready',{'screen':'trial','trial':{'ready':True}}),('review',{}),('review-stopped',{'screen':'review','stopped':True}),('running',{}),('running-complete',{'screen':'running','run':{'complete':True}}),('running-interrupted',{'screen':'running','run':{'interrupted':True}}),('results',{}),('save-none',{'screen':'save','formats':[]}),('save',{})]
cases=[]
for lang in ['ko','en']:
 for name,extra in variants:
  state=dict(screen=name,connected=False,busy=False,selected=['data','schema'],tables=['demo.Customers'],trial=dict(ready=False,consent=False),stopped=False,run=dict(complete=False,interrupted=False),formats=['json'])
  for key,value in extra.items():
   if isinstance(value,dict):state[key].update(value)
   else:state[key]=value
  cases.append(dict(id=lang+'-'+name,lang=lang,state=state))
(o/'footer-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
html='''<!doctype html><meta charset="utf-8"><title>ActionFooter · original isolation</title><link rel="stylesheet" href="footer-original.css"><style>body{min-width:1000px}#foot-controls{position:fixed;left:30px;top:380px;width:740px;z-index:10;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.fixture{margin:72px 0 28px 30px;width:calc(100vw - 220px)}.fixture .footer{width:100%}.fixture:not(:first-child){position:absolute;left:0}.fixture:not(:first-child){visibility:hidden}</style><div id="foot-controls"><button id="foot-record">Record footer</button><select id="foot-case" aria-label="Footer case"></select><output id="foot-out">Ready</output><button id="foot-connect">Connect case</button><button id="foot-busy">Busy case</button><button id="foot-none">No checks case</button><button id="foot-ready">Trial ready case</button><button id="foot-locale">KO / EN</button></div><div id="fixtures"></div><script>let lang='ko',state={},requests=[];'''+defs+'\nconst cases='+json.dumps(cases,ensure_ascii=False)+''';const hydrate=s=>({...s,selected:new Set(s.selected),tables:new Set(s.tables),formats:new Set(s.formats)});for(const [i,c] of cases.entries()){lang=c.lang;state=hydrate(c.state);const f=document.createElement('section');f.className='fixture';f.dataset.id=c.id;f.innerHTML='<footer class="footer">'+footer()+'</footer>';if(i){f.style.top=(i*200)+'px';f.setAttribute('aria-hidden','true')}document.getElementById('fixtures').append(f);const opt=document.createElement('option');opt.value=c.id;opt.textContent=c.id;document.getElementById('foot-case').append(opt)}document.getElementById('foot-case').onchange=e=>{for(const f of document.querySelectorAll('.fixture')){const active=f.dataset.id===e.target.value;f.style.visibility=active?'visible':'hidden';f.style.top=active?'0px':(Number(cases.findIndex(c=>c.id===f.dataset.id))*200)+'px';f.style.position='absolute';f.setAttribute('aria-hidden',String(!active))}requests=[];document.getElementById('foot-out').textContent='Case '+e.target.value};for(const [id,name] of [['foot-connect','connect'],['foot-busy','connect-busy'],['foot-none','select-none'],['foot-ready','trial-ready'],['foot-locale','locale']])document.getElementById(id).onclick=()=>{const picker=document.getElementById('foot-case'),parts=picker.value.split('-');const next=name==='locale'?(parts[0]==='ko'?'en':'ko')+'-'+parts.slice(1).join('-'):parts[0]+'-'+name;picker.value=next;picker.onchange({target:picker})};function read(){return [...document.querySelectorAll('.fixture')].map(f=>{const foot=f.querySelector('.footer'),r=foot.getBoundingClientRect(),box=x=>{const b=x.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}},hint=foot.querySelector('.footer-hint'),actions=foot.querySelector('.footer-actions'),s=getComputedStyle(foot);return{id:f.dataset.id,width:r.width,height:r.height,paddingX:parseFloat(s.paddingLeft),hint:{box:box(hint),text:hint.textContent},actions:actions?box(actions):null,buttons:[...foot.querySelectorAll('button')].map(b=>({box:box(b),action:b.dataset.action,enabled:!b.disabled,label:b.textContent,name:b.getAttribute('aria-label')||b.textContent,variant:b.classList.contains('primary')?'primary':b.classList.contains('danger')?'danger':'quiet',icon:b.querySelector('.spinner')?'spinner':b.querySelector('svg')?.innerHTML||''}))}})}document.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;press(b);requests.push({action:b.dataset.action,trusted:e.isTrusted,focused:document.activeElement===b,focusVisible:b.matches(':focus-visible')});document.getElementById('foot-out').textContent='Requested '+b.dataset.action});document.getElementById('foot-record').onclick=async()=>{await document.fonts.ready;const response=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,viewport:innerWidth,rows:read(),requests,active:document.activeElement?.dataset.action||document.activeElement?.id||'',reduced:matchMedia('(prefers-reduced-motion:reduce)').matches})});if(!response.ok)throw Error('Evidence failed');document.getElementById('foot-out').textContent='Footer recorded'};</script>'''
(o/'actionfooter.html').write_text(html)
for p in [o/'footer-cases.json',r/'docs/replica/source/footer-cases.json']:p.write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n')
print(len(cases),'original footer branch fixtures prepared')
